 internal string LoadTaskDraft(string path){if(taskDrafts==null||draftHome!=store.Home){draftHome=store.Home;string file=Path.Combine(store.Home,".jago","task-drafts.json");try{taskDrafts=File.Exists(file)?Store.Json.Deserialize<Dictionary<string,string>>(File.ReadAllText(file)):new Dictionary<string,string>();}catch{taskDrafts=new Dictionary<string,string>();}}string value;return taskDrafts.TryGetValue(store.Relative(path),out value)?value:"";}
 internal void SaveTaskDraft(string path,string value){string previous=LoadTaskDraft(path);if(previous==value)return;taskDrafts[store.Relative(path)]=value;Store.Atomic(Path.Combine(store.Home,".jago","task-drafts.json"),Store.Json.Serialize(taskDrafts));}
 internal void ApplyNotebookSpelling(){editor.SpellLanguage=store.Pref.SpellLanguage;editor.SpellEnabled=store.Pref.SpellEnabled;taskEntry.SpellEnabled=store.Pref.SpellEnabled;taskEntry.SpellLanguage=store.Pref.SpellLanguage;taskEntry.ThemeMenu=menu=>{ThemeMenu(menu);PreparePopup(menu);};if(spellButton!=null)spellButton.Text=store.Pref.SpellEnabled?"Spelling on":"Spelling off";}
 internal void SetNotebookFont(string family,float size){size=Math.Max(8,Math.Min(48,size));try{editor.Font=new Font(family,size);tasks.Font=editor.Font;UpdatePageView();taskEntry.Font=new Font("Segoe UI",10);taskRow.Height=42;store.Pref.EditorFont=family;store.Pref.EditorSize=size;store.SavePrefs();if(fontButton!=null)fontButton.Text=family;if(sizeButton!=null)sizeButton.Text=size+" pt";}catch(Exception e){Tell(e.Message);}}
 internal void AddSizeMenu(ToolStripDropDownButton button,Func<float> currentSize,Action<float> change){foreach(float n in new float[]{9,10,11,12,14,16,18,22,28,36,48}){float value=n;var item=new ToolStripMenuItem(n+" pt");item.Click+=(s,e)=>change(value);button.DropDownItems.Add(item);}button.DropDownOpening+=(s,e)=>{foreach(ToolStripMenuItem item in button.DropDownItems)item.Checked=item.Text==currentSize()+" pt";};}
 internal void ChooseFont(Form parent,string family,float size,string theme,Action<string,float> change){using(var f=Dialog("Font · live preview",520,550)){var searchFont=new TextBox{Dock=DockStyle.Top};var list=new ListBox{Dock=DockStyle.Fill,BorderStyle=BorderStyle.None};var sample=new Label{Text="A quick idea. A useful list. 0123456789",Dock=DockStyle.Bottom,Height=80,TextAlign=ContentAlignment.MiddleCenter};var sizes=new StableToolStrip{Dock=DockStyle.Bottom,GripStyle=ToolStripGripStyle.Hidden};float chosenSize=size;string chosenFont=family;var sizeMenu=new ToolStripDropDownButton(size+" pt");AddSizeMenu(sizeMenu,()=>chosenSize,value=>{chosenSize=value;sizeMenu.Text=value+" pt";sample.Font=new Font(chosenFont,value);change(chosenFont,value);});sizes.Items.Add(sizeMenu);Add(sizes,"A−",()=>{chosenSize=Math.Max(8,chosenSize-1);sample.Font=new Font(chosenFont,chosenSize);sizeMenu.Text=chosenSize+" pt";change(chosenFont,chosenSize);});Add(sizes,"A+",()=>{chosenSize=Math.Min(48,chosenSize+1);sample.Font=new Font(chosenFont,chosenSize);sizeMenu.Text=chosenSize+" pt";change(chosenFont,chosenSize);});Add(sizes,"Done",()=>f.Close());string[] fonts=FontFamily.Families.Select(x=>x.Name).Distinct().OrderBy(x=>x).ToArray();Action refresh=()=>{list.Items.Clear();foreach(string name in fonts.Where(x=>x.IndexOf(searchFont.Text,StringComparison.OrdinalIgnoreCase)>=0))list.Items.Add(name);list.SelectedItem=chosenFont;};list.SelectedIndexChanged+=(s,e)=>{if(list.SelectedItem==null)return;chosenFont=Convert.ToString(list.SelectedItem);sample.Font=new Font(chosenFont,chosenSize);change(chosenFont,chosenSize);};searchFont.TextChanged+=(s,e)=>refresh();f.Controls.Add(list);f.Controls.Add(sample);f.Controls.Add(sizes);f.Controls.Add(searchFont);Native.Cue(searchFont,"Find an installed font…");CompanionPalette.Apply(f,theme);refresh();sample.Font=new Font(family,size);f.ShowDialog(parent);}}
 internal void BuildSpellingMenu(ToolStripDropDownButton button,Func<bool> getEnabled,Action<bool> enabled,Func<string> getLanguage,Action<string> language,Func<string> theme=null){button.DropDownOpening+=(s,e)=>{button.DropDownItems.Clear();var on=new ToolStripMenuItem("Check spelling as I type"){Checked=getEnabled()};on.Click+=(ss,ee)=>enabled(!getEnabled());button.DropDownItems.Add(on);string[] available=WindowsSpelling.Languages();if(available.Length==0){button.DropDownItems.Add("No Windows spelling language installed").Enabled=false;return;}var menu=new ToolStripMenuItem("Language");string selected=WindowsSpelling.DefaultLanguage(getLanguage());foreach(string tag in available){string value=tag;var item=new ToolStripMenuItem(tag){Checked=selected==tag};item.Click+=(ss,ee)=>language(value);menu.DropDownItems.Add(item);}button.DropDownItems.Add(menu);button.DropDownItems.Add("Right-click an underlined word for suggestions").Enabled=false;string selectedTheme=theme==null?store.Pref.Theme:theme();button.DropDown.Renderer=new ToolStripProfessionalRenderer(new CompanionColors(CompanionPalette.For(selectedTheme)[1],CompanionPalette.For(selectedTheme)[0],CompanionPalette.For(selectedTheme)[4]));CompanionPalette.Items(button.DropDownItems,CompanionPalette.For(selectedTheme));};}
 internal void RenamePage(Note n){if(n==null||!SaveNow())return;string name=Ask("Rename page","Name for this page · its text stays unchanged",n.Title);if(String.IsNullOrWhiteSpace(name))return;store.SetTitle(n,name);if(current!=null&&current.Path==n.Path){current.Title=name;heading.Text=name;}foreach(var memo in memos.Where(x=>x.NotePath==n.Path))memo.RefreshTitle();RefreshNotes();}
 internal void DeletePage(Note pageToDelete,bool confirm){if(pageToDelete==null)return;if(!SaveNow())return;foreach(var m in memos.Where(x=>x.NotePath==pageToDelete.Path).ToArray())if(!m.Flush())return;if(confirm&&!ConfirmDelete(pageToDelete.Title))return;string original=pageToDelete.Path;string trash=store.Trash(pageToDelete);deletedPages.Push(new DeletedPage{Original=original,Trash=trash});foreach(var m in memos.Where(x=>x.NotePath==original).ToArray())m.Close();if(current==pageToDelete||current!=null&&current.Path==original){current=null;dirty=false;loading=true;editor.Clear();editor.ReadOnly=true;heading.Text="Choose a page or create one";loading=false;}RefreshNotes();if(current==null&&store.Notes.Count>0){editor.ReadOnly=false;SelectNote(store.Notes[0]);}Tell("Page moved to Trash · Undo deletion is in Pages or Ctrl+Z on the page list");}
 internal bool ConfirmDelete(string title){using(var f=Dialog("Delete page?",460,235)){var body=new Label{Text="Move “"+title+"” to Trash? You can restore it afterwards. Closing a sticky alone keeps its page.",Dock=DockStyle.Fill};var row=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48};var delete=new Button{Text="Move to Trash",AutoSize=true,DialogResult=DialogResult.OK};var cancel=new Button{Text="Cancel",AutoSize=true,DialogResult=DialogResult.Cancel};row.Controls.Add(delete);row.Controls.Add(cancel);f.Controls.Add(body);f.Controls.Add(row);ThemeControls(f);return f.ShowDialog(this)==DialogResult.OK;}}
 internal void RestoreDeletedPage(){if(deletedPages.Count>0&&deletedPages.Peek().Group!=null){string group=deletedPages.Peek().Group;while(deletedPages.Count>0&&deletedPages.Peek().Group==group){deletedPages.Peek().Group=null;RestoreDeletedPage();}return;}if(deletedPages.Count==0){Tell("No page deletion to undo in this session. Saved pages remain in the Trash folder.");return;}var item=deletedPages.Pop();if(!File.Exists(item.Trash)){Tell("That Trash file is no longer available.");return;}string target=item.Original;if(File.Exists(target))target=Path.Combine(Path.GetDirectoryName(target),"Restored-"+Guid.NewGuid().ToString("N").Substring(0,6)+"-"+Path.GetFileName(target));Directory.CreateDirectory(Path.GetDirectoryName(target));File.Move(item.Trash,target);store.Reload();var note=store.Notes.First(n=>n.Path==target);editor.ReadOnly=false;SelectNote(note);RefreshNotes();Tell("Page restored");}
 internal string ConfiguredCaptureAction(){try{var data=Store.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(Program.Config,"capture-launcher.json")));return Convert.ToString(data["Action"]);}catch{return store.Pref.CaptureAction;}}
 internal void CaptureHome(){using(var f=Dialog("Jago Capture · quick screenshots & clips",560,550)){var col=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};col.Controls.Add(new Label{Text="One click to capture. A preview to choose what happens next.",AutoSize=true,MaximumSize=new Size(480,0),Font=new Font(Font,FontStyle.Bold)});Action<string,Action> action=(title,run)=>{var b=new Button{Text=title,Width=470,Height=38};b.Click+=(s,e)=>{f.Close();run();};col.Controls.Add(b);};action("Screenshot a region",()=>BeginCapture("edit-region"));action("Screenshot an application window",()=>BeginCapture("window"));action("Record a video snippet",VideoSnippet);action("Browse saved captures",CaptureShelf);col.Controls.Add(new Label{Text="Taskbar shortcut",AutoSize=true,Font=new Font(Font,FontStyle.Bold),Margin=new Padding(0,12,0,4)});col.Controls.Add(new Label{Text="Jago Capture is a separate launcher beside Companion. Open it once, then right-click its taskbar icon and choose Pin to taskbar. Its right-click menu includes region, window and video actions.",MaximumSize=new Size(470,0),AutoSize=true});var choice=new ThemeComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=470};var labels=new[]{"Region screenshot","Application window","Video snippet","Capture chooser"};var values=new[]{"region","window","video","chooser"};choice.Items.AddRange(labels);choice.SelectedIndex=Math.Max(0,Array.IndexOf(values,ConfiguredCaptureAction()));choice.SelectedIndexChanged+=(s,e)=>{store.Pref.CaptureAction=values[choice.SelectedIndex];Store.Atomic(Path.Combine(Program.Config,"capture-launcher.json"),Store.Json.Serialize(new{Action=store.Pref.CaptureAction,Introduced=true}));store.SavePrefs();};col.Controls.Add(new Label{Text="When clicking the pinned Capture icon",AutoSize=true});col.Controls.Add(choice);action("Open Jago Capture launcher",()=>System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Path.Combine(